#[test]
fn unit_metadata() {
    let info = TemperatureChangeRate::<f64>::INFO;
    assert_eq!(info.name, "TemperatureChangeRate");
    assert_eq!(info.units.len(), TemperatureChangeRateUnit::ALL.len());
    for (&unit, unit_info) in TemperatureChangeRateUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(
        info.base_unit,
        TemperatureChangeRateUnit::DegreeCelsiusPerSecond.info()
    );
}

