#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [TemperatureChangeRate; 17] = [
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeCelsiusPerSecond),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::NanodegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::MicrodegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::MillidegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::CentidegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::DecidegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::DecadegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::HectodegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::KilodegreeCelsiusPerSecond,
        ),
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeCelsiusPerMinute),
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeKelvinPerMinute),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::DegreeFahrenheitPerMinute,
        ),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::DegreeFahrenheitPerSecond,
        ),
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeKelvinPerSecond),
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeCelsiusPerHour),
        TemperatureChangeRate::const_new(1234.5, TemperatureChangeRateUnit::DegreeKelvinPerHour),
        TemperatureChangeRate::const_new(
            1234.5,
            TemperatureChangeRateUnit::DegreeFahrenheitPerHour,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(TemperatureChangeRateUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            TemperatureChangeRate::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in TemperatureChangeRateUnit::ALL {
            assert_eq!(
                TemperatureChangeRate::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                TemperatureChangeRate::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = TemperatureChangeRate::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            TemperatureChangeRate::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in TemperatureChangeRateUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        TemperatureChangeRate::from_base(0.0).auto_unit().unit,
        TemperatureChangeRateUnit::DegreeCelsiusPerSecond
    );
}

